-- HOLIDAYS · Halloween · Halloween · 4–6
do $mig$
declare
  v_course uuid; v_unit uuid; v_lesson uuid;
  v_media text := 'https://classroom.wowteach.ru/media/';
begin
  select id into v_course from classroom_courses where slug = 'holidays';
  if v_course is null then raise exception 'course holidays not found'; end if;

  select id into v_unit from classroom_units
   where course_id = v_course and title = 'Halloween' limit 1;
  if v_unit is null then
    insert into classroom_units (course_id, title, sort_order)
    values (v_course, 'Halloween', 1) returning id into v_unit;
  end if;

  select id into v_lesson from classroom_lessons
   where unit_id = v_unit and title = 'Halloween · 4–6' limit 1;
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, summary, sort_order, is_published, pass_threshold, kind)
    values (v_unit, 'Halloween · 4–6', 'Урок-игра для 4–6 лет', 0, false, 60, 'lesson')
    returning id into v_lesson;
  else
    update classroom_lessons set summary = 'Урок-игра для 4–6 лет', sort_order = 0,
           is_published = false, pass_threshold = 60, kind = 'lesson'
     where id = v_lesson;
  end if;

  insert into classroom_blocks (lesson_id, type, payload, sort_order) values
    -- блок 1 (sort_order 0) · кнопка: урок в новой вкладке
    (v_lesson, 'text', replace($blk${"html": "<div style=\"text-align:center;padding:22px 16px;background:linear-gradient(180deg,#fff7ec,#ffe9cc);border-radius:18px;border:2px solid #f3d3a3\">\n<h2 style=\"margin:0 0 6px;color:#8a3c08\">🎃 Halloween · 4–6</h2>\n<p style=\"margin:0 0 16px;color:#6b4a2a\">Интерактивный урок. Откройте его и демонстрируйте в Zoom <b>эту вкладку</b>, а не весь экран.</p>\n<p style=\"margin:0\"><a href=\"https://classroom.wowteach.ru/lessons/halloween/4-6.html\" style=\"display:inline-block;padding:14px 38px;border-radius:99px;background:#c0612b;color:#fff;font-weight:700;font-size:18px;text-decoration:none\">▶ Открыть урок на весь экран</a></p>\n<p style=\"margin:14px 0 0;color:#8a6a4a;font-size:13px\">План урока — кнопка 📋 вверху справа внутри урока (откроется отдельным окном) или ниже на этой странице.<br>Нужен интернет: картинки и музыка загружаются с сервера.</p></div>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 0),
    -- блок 2 (sort_order 1) · превью урока
    (v_lesson, 'embed', replace($blk${"url": "https://classroom.wowteach.ru/lessons/halloween/4-6.html"}$blk$, '@@MEDIA@@', v_media)::jsonb, 1),
    -- блок 3 (sort_order 2) · план — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<h3>План урока</h3>\n\n<div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>Цель:</b> ввести 4 слова (ghost, bat, spider, monster), эмоции, фразу I like / I don't like. &nbsp; <b>Длительность:</b> 20–30 мин. &nbsp; <b>Уровень:</b> 4–6, начинающие. &nbsp; <b>Мотивация:</b> украшение комнаты дракона, в конце — фото на память.</div>\n\n<table style=\"width:100%;border-collapse:collapse;font-size:14px\">\n<tr><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Стр.</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Задание и инструкция</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Teacher's language (англ.)</th></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">1</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Warm-up: угадай праздник.</b> Картинка с символами Хэллоуина, на экране ничего не написано — вопросы задаёт учитель. Ученик называет, что видит, и угадывает праздник.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Look! What can you see?\" \"What colour is it?\" \"What holiday is it?\" \"Yes! It's Halloween!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">2</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>How do you feel?</b> Три тыквы-эмоции. Ученик выбирает свою и говорит. Учитель нажимает на выбранную тыкву.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"How do you feel today?\" \"Are you happy?\" \"I'm happy too!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">3</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Выбери костюм.</b> Дракон-вампир / привидение / тыква. Ученик выбирает — дракон в этом костюме будет жить в комнате и танцевать в бонусной игре.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Choose a costume!\" \"A vampire? A ghost? A pumpkin?\" \"Wow, cool!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">4</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Новые слова.</b> Одна страница, четыре слова подряд: ghost, bat, spider, monster. Появляется картинка — учитель сразу говорит «It's a ghost!», ученик повторяет. Следующее слово — кнопка Next (или нажать на картинку). Кружочки вверху показывают раунды.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Look! It's a ghost!\" \"Say: ghost!\" \"Great!\" \"And this? It's a bat!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">5</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Комната дракона.</b> Пустая комната: «Давай украсим её к Хэллоуину!». За каждую игру в комнате будет появляться новое украшение.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Look! This is the dragon's room.\" \"It's empty!\" \"Let's decorate it!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">6</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Волшебный туман (4 раунда).</b> Картинку закрывает густой туман, он очень медленно рассеивается. Ученик старается угадать как можно раньше. Угадал — учитель нажимает на картинку (или 👀): туман исчезает, звучит «правильно». Кружочки вверху показывают раунды. После игры загорается кнопка Next — нажмите её: откроется комната дракона, новый предмет подсветится. Спросите «What's new?» — ученик называет. Ещё раз Next — дальше. В комнате появляется: <b>кровать</b>.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What's this?\" \"Is it a bat?\" \"Look… It's a spider!\" \"What's new? A bed!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">7</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Пантомима.</b> Учитель показывает слово телом, ученик угадывает и нажимает на картинку. <i>Подсказки:</i> ghost — парит, «Boo!»; bat — машет крыльями; spider — пальцы-лапки ползут; monster — рычит, когти. После игры загорается кнопка Next — нажмите её: откроется комната дракона, новый предмет подсветится. Спросите «What's new?» — ученик называет. Ещё раз Next — дальше. В комнате появляется: <b>коврик</b>.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What am I?\" \"Guess!\" \"Yes, a bat! Well done!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">8</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Knock, knock! (5 дверей).</b> Ученик выбирает дверь по номеру: «Number three!». Учитель жмёт на дверь — стук, дверь открывается, выпрыгивает персонаж. <b>Ученик сам называет:</b> «It's a ghost!» (подпись появляется через пару секунд). За одной дверью конфеты: «Trick or treat!». После игры загорается кнопка Next — нажмите её: откроется комната дракона, новый предмет подсветится. Спросите «What's new?» — ученик называет. Ещё раз Next — дальше. В комнате появляется: <b>шторы</b>.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Knock, knock! Who's there?\" \"Which door? Number two?\" \"What is it?\" \"Yes! It's a bat!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">9</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Фонарик (4 раунда).</b> Экран тёмный, картинки спрятаны в разных местах — без фонарика их не видно. Учитель водит фонарик мышкой (если мышь не трогать, он медленно бродит сам). Ученик говорит, куда светить, и ищет нужного персонажа. Нашли — учитель нажимает на картинку под фонариком. Кроме четырёх слов спрятаны тыква и конфеты — их называем тоже. Кружочки вверху показывают раунды. После игры загорается кнопка Next — нажмите её: откроется комната дракона, новый предмет подсветится. Спросите «What's new?» — ученик называет. Ещё раз Next — дальше. В комнате появляется: <b>гирлянда</b>.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Find the monster!\" \"Is it here?\" \"No, it's a pumpkin!\" \"Yes! There it is!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">10</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Peekaboo — кто прячется? (4 раунда).</b> Персонаж прячется в комнате дракона: заглядывает в окно, за изголовьем кровати, за дверью, за кроватью — видно только кусочек. Ученик угадывает, учитель нажимает на него (или 👀) — персонаж выпрыгивает. Кружочки вверху показывают раунды. После игры загорается кнопка Next — нажмите её: откроется комната дракона, новый предмет подсветится. Спросите «What's new?» — ученик называет. Ещё раз Next — дальше. В комнате появляется: <b>летучие мыши</b>.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Who's hiding?\" \"Look! What's this?\" \"Is it a ghost?\" \"Boo! It's a monster!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">11</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Волшебный котёл — считаем конфеты (3 раунда).</b> Вверху число: «Put 3 🍬 in!». Ученик кладёт в котёл конфеты (любые) — учитель перетаскивает или просто нажимает на конфету — и <b>считает вслух вместе с учителем</b>. Рядом с котлом растёт цифра. Набрали — «пуф!», зелье меняет цвет, из котла выглядывает сюрприз. Кружочки вверху показывают раунды. После игры загорается кнопка Next — нажмите её: откроется комната дракона, новый предмет подсветится. Спросите «What's new?» — ученик называет. Ещё раз Next — дальше. В комнате появляется: <b>тыква на полке</b>.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Put three candies in!\" \"One candy, two candies, three candies!\" \"Poof! Magic!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">12</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>I like / I don't like (4 карточки).</b> Ученик говорит «I like ghosts» или «I don't like spiders». Учитель нажимает 👍 или 👎. Кружочки вверху показывают раунды. После игры загорается кнопка Next — нажмите её: откроется комната дракона, новый предмет подсветится. Спросите «What's new?» — ученик называет. Ещё раз Next — дальше. В комнате появляется: <b>конфеты</b>.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Do you like ghosts?\" \"I like ghosts!\" \"I don't like spiders!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">13</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>What's missing? (2 раунда).</b> Четыре картинки. Через пару секунд прилетает тучка, накрывает одну картинку и улетает вместе с ней. Ученик угадывает, что пропало. Учитель нажимает 👀 — картинка возвращается. Кружочки вверху показывают раунды. После игры загорается кнопка Next — нажмите её: откроется комната дракона, новый предмет подсветится. Спросите «What's new?» — ученик называет. Ещё раз Next — дальше. В комнате появляется: <b>монстрик</b>.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Look carefully!\" \"Close your eyes!\" \"What's missing?\" \"Yes! The bat is missing!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">14</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Bonus games (если есть время).</b> Можно сыграть во все, в любом порядке, или сразу нажать <b>Finish 🏁</b>. После каждой игры — кнопка 🎁: в комнате появляется новое украшение (паучок, потом привидение), затем кнопка «🎮 ←» возвращает к списку игр.<br>• <b>Dance 💃</b>: сначала разберите с учеником четыре карточки — учитель показывает движение, ученик повторяет (bat — машем крыльями, ghost — летаем и говорим «Boo!», spider — ползаем пальцами, monster — рычим и показываем когти). Потом ▶: музыка, дракон танцует, ученик танцует тоже. Музыка останавливается — появляется картинка, ученик показывает это движение. ▶ — танцуем дальше.<br>• <b>Memory 🧩</b>: найти пары, называя слова.<br>• <b>Shadows 👤</b>: найти тень картинки.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Let's dance!\" \"Stop! What is it? Show me!\" \"Fly like a bat!\" \"Find the pairs!\"</td></tr>\n<tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">15</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Финал: фото комнаты.</b> Комната полностью украшена. «Save photo» — скачать картинку и отправить ученику/родителям. Стрелка ← возвращает к бонусным играм, если нажали случайно.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Look at your room! Amazing!\" \"Happy Halloween!\" \"Well done!\"</td></tr>\n</table>\n\n<div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🗂️ Лексика урока:</b> ghost, bat, spider, monster • happy, sad, angry • bed, rug, curtains, lights, pumpkin, candy • I like / I don't like • numbers 1–5: one candy, two candies… • \"Trick or treat!\", \"Happy Halloween!\", \"Boo!\", \"What's new?\"</div>\n<div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0;font-size:13px;color:#777\"><b>Навигация:</b> стрелки ← → внизу экрана — вернуться или пропустить страницу; центральная кнопка Next загорается, когда задание выполнено. Номера страниц внизу справа соответствуют этой таблице. 📋 — этот план, 🎵 — фоновая музыка (вкл/выкл и громкость).</div>\n<div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🏠 Домашнее задание</b> — материал <b>«Halloween Homework · 4–6»</b> на платформе: «Материалы» → «Задать ДЗ» → ученик → отметить. Только слова урока, 10–15 минут. Задания:<ol style=\"margin:6px 0 0 22px\"><li>Карточки: смотри, слушай, повторяй</li><li>Послушай и выбери картинку</li><li>Найди одинаковые картинки (соедини пары и назови)</li><li>Послушай слово: 👍 или 👎</li><li>🎤 Назови, что видишь на картинке</li></ol><div style=\"color:#777;font-size:13px;margin-top:4px\">Устные задания ученик записывает голосом — их вы слушаете и оцениваете в «Проверке ДЗ».</div></div>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 2),
    -- блок 4 (sort_order 3) · ДЗ — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<h3>Домашнее задание</h3><p>Материал <b>«Halloween Homework · 4–6»</b> в этом же юните. «Материалы» → «Задать ДЗ» → ученик → отметить.</p>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 3)
  on conflict (lesson_id, sort_order) do update
    set type = excluded.type, payload = excluded.payload;

  delete from classroom_blocks where lesson_id = v_lesson and sort_order >= 4;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 0;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 2;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 3;
end
$mig$;
